-- S197 — Vincent's Word Studies (NT expository) base load.
-- Source: source-texts/vincents-word-studies/vincents-structured.json (S196).
-- PD base (Marvin R. Vincent, 1886–1900, d.1922). Framework correction rides
-- in tool_annotations (tool='vincents'); this is the untouched annotated-foil base.
-- Re-runnable: ON CONFLICT (entry_key) DO UPDATE.

BEGIN;

CREATE TABLE IF NOT EXISTS vincents_entries (
    id          BIGSERIAL PRIMARY KEY,
    entry_key   TEXT NOT NULL UNIQUE,         -- '<book>.<ch>.<v>:<headword-slug>'
    book_slug   TEXT NOT NULL,
    chapter     INT  NOT NULL,
    verse       INT  NOT NULL,
    verse_key   TEXT NOT NULL,                -- '<book>.<ch>.<v>' (annotation lookup key)
    headword    TEXT,
    body        TEXT NOT NULL,
    source_vol  TEXT
);
CREATE INDEX IF NOT EXISTS idx_vincents_verse ON vincents_entries(book_slug, chapter, verse);
CREATE INDEX IF NOT EXISTS idx_vincents_verse_key ON vincents_entries(verse_key);

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

ON CONFLICT (entry_key) DO UPDATE SET book_slug=EXCLUDED.book_slug, chapter=EXCLUDED.chapter, verse=EXCLUDED.verse, verse_key=EXCLUDED.verse_key, headword=EXCLUDED.headword, body=EXCLUDED.body, source_vol=EXCLUDED.source_vol;

DO $v$ DECLARE n INT; BEGIN
  SELECT COUNT(*) INTO n FROM vincents_entries;
  RAISE NOTICE 'session197 vincents: % rows', n;
  IF n < 4501 THEN RAISE EXCEPTION 'vincents load short: %', n; END IF;
END $v$;

COMMIT;
